import{_ as e,o as d,c as o,a6 as c}from"./chunks/framework.B_q3ZJNF.js";const b=JSON.parse('{"title":"练习路线：从红到绿重写一遍","description":"","frontmatter":{"title":"练习路线：从红到绿重写一遍"},"headers":[],"relativePath":"mini-redis-course/exercises.md","filePath":"mini-redis-course/docs/exercises.md"}'),s={name:"mini-redis-course/exercises.md"};function r(i,t,a,l,n,p){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="练习路线-从红到绿重写一遍" tabindex="-1">练习路线：从红到绿重写一遍 <a class="header-anchor" href="#练习路线-从红到绿重写一遍" aria-label="Permalink to &quot;练习路线：从红到绿重写一遍&quot;">​</a></h1><p>读完一遍只是看着别人写。要把它变成自己的，最硬的路线是：<strong>清空实现，按章序让 101 条测试从红一条条转绿</strong>。测试文件就是梯子——每章一个文件、append-only、先红后绿，这是全书生成时就钉死的结构，天然是一套按难度排序的作业。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ol><li>备份或另 clone 一份 <code>companion/</code>（别在正本上动手）。</li><li>删掉 <code>companion/src/</code> 下全部 <code>.ts</code> 文件——<strong>保留 <code>tests/</code>、<code>package.json</code>、<code>tsconfig.json</code></strong>。</li><li><code>npm install</code> 后跑 <code>npm test</code>：全红（import 不到实现）。这就是起点。</li></ol><h2 id="梯子" tabindex="-1">梯子 <a class="header-anchor" href="#梯子" aria-label="Permalink to &quot;梯子&quot;">​</a></h2><p>按章序走，每章的测试文件名就是路标：</p><table tabindex="0"><thead><tr><th>步</th><th>测试文件</th><th>你要写出什么</th><th>提示（正文出处）</th></tr></thead><tbody><tr><td>1</td><td><code>tests/resp-protocol.test.ts</code>（18 条）</td><td><code>resp.ts</code> 的编码器与 RespDecoder、<code>db.ts</code> 的 PING/SET/GET/DEL、<code>server.ts</code> 雏形、<code>client.ts</code></td><td>第 2 章</td></tr><tr><td>2</td><td><code>tests/single-thread-event-loop.test.ts</code>（6 条）</td><td><code>naive-server.ts</code> 串行反例、<code>client.ts</code> 的 pipe</td><td>第 3 章</td></tr><tr><td>3</td><td><code>tests/hash-table-rehash.test.ts</code>（10 条）</td><td><code>dict.ts</code>（链地址、翻倍扩容、渐进 rehash）</td><td>第 4 章</td></tr><tr><td>4</td><td><code>tests/skiplist-zset.test.ts</code>（14 条）</td><td><code>skiplist.ts</code>（随机层数可注入）、<code>db.ts</code> 加 ZADD/ZRANGE/ZCARD</td><td>第 5 章</td></tr><tr><td>5</td><td><code>tests/ttl-expire.test.ts</code>（19 条）</td><td><code>expire.ts</code>、<code>db.ts</code> 接入 SET EX/EXPIRE/TTL/KEYS 与节流周期</td><td>第 6 章</td></tr><tr><td>6</td><td><code>tests/eviction-lru.test.ts</code>（12 条）</td><td><code>eviction.ts</code>、<code>db.ts</code> 接入 CONFIG 与内存关</td><td>第 7 章</td></tr><tr><td>7</td><td><code>tests/aof.test.ts</code>（13 条）</td><td><code>aof.ts</code>、<code>db.ts</code> 接入记账与 BGREWRITEAOF</td><td>第 8 章</td></tr><tr><td>8</td><td><code>tests/rdb-snapshot.test.ts</code>（9 条）</td><td><code>rdb.ts</code>、<code>db.ts</code> 接入 SAVE/LOAD/FLUSHALL</td><td>第 9 章</td></tr></tbody></table><p>两个超前依赖要注意：</p><ul><li>第 1 步的 <code>server.ts</code> 雏形要能过 TCP 往返测试——事件驱动的写法第 3 章才讲透，第 1 步照第 2 章的挂接回调写即可，别急着理解为什么它天然支持管道。</li><li>第 4 步起 <code>db.ts</code> 的键空间是 <code>Dict&lt;string | SkipList&gt;</code>（第 5 章），第 1 步先用 <code>Map</code>、第 3 步换 <code>Dict</code>——与正文演进顺序一致。</li></ul><h2 id="玩法" tabindex="-1">玩法 <a class="header-anchor" href="#玩法" aria-label="Permalink to &quot;玩法&quot;">​</a></h2><ul><li>每步先跑该章测试看红在哪，再回正文对应章读「演练」槽，动手转绿；全绿前不进下一步。</li><li>卡死超过半小时：回正文找「验证」槽的小破坏实验，反着做一遍（先看哪条红），往往就通了。</li><li>全部转绿后，<code>node src/boot.ts</code> + <code>redis-cli -p 6399</code> 走一遍第 2 章验证槽——那是毕业典礼。</li></ul><p>毕业的判据只有一条：<code>npm test</code> 全绿，且你能对着任何一个红过的地方讲清「它为什么红」。</p>',12)])])}const m=e(s,[["render",r]]);export{b as __pageData,m as default};
